def length_of_lis(nums):
    n = len(nums)
    best = 0
    def dfs(start, prev, length):
        nonlocal best
        best = max(best, length)
        for i in range(start, n):
            if nums[i] > prev:
                dfs(i + 1, nums[i], length + 1)
    dfs(0, float('-inf'), 0)
    return best

